import { forwardRef, type SVGAttributes } from "react";
import { sparklineDefaults, type SparklineSpecProps } from "../generated/sparkline.types";

// Plain markup with no hooks, so it also works in a React Server Component.

export interface SparklineProps
  extends SparklineSpecProps,
    Omit<SVGAttributes<SVGSVGElement>, keyof SparklineSpecProps | "children"> {}

const colors: Record<NonNullable<SparklineSpecProps["color"]>, string> = {
  primary: "var(--rd-color-chart-1)",
  success: "var(--rd-color-feedback-success)",
  danger: "var(--rd-color-feedback-danger)",
  muted: "var(--rd-color-text-muted)",
};

const PAD = 2;
const round = (n: number) => Math.round(n * 100) / 100;

export const Sparkline = forwardRef<SVGSVGElement, SparklineProps>(function Sparkline(
  {
    data,
    type = sparklineDefaults.type,
    label,
    width = sparklineDefaults.width,
    height = sparklineDefaults.height,
    color = sparklineDefaults.color,
    showLast = sparklineDefaults.showLast,
    ...rest
  },
  ref,
) {
  const values = (data ?? []).filter((v) => typeof v === "number" && Number.isFinite(v));
  const stroke = colors[color];
  const a11y = label ? { role: "img" as const, "aria-label": label } : { "aria-hidden": true as const };

  let shapes: React.ReactNode = null;
  if (values.length > 0 && type === "bar") {
    const lo = Math.min(0, ...values);
    const hi = Math.max(0, ...values);
    const range = hi - lo || 1;
    const inner = height - PAD * 2;
    const y = (v: number) => PAD + ((hi - v) / range) * inner;
    const slot = (width - PAD * 2) / values.length;
    const barWidth = Math.max(1, slot * 0.7);
    shapes = values.map((v, i) => {
      const top = Math.min(y(v), y(0));
      const barHeight = Math.max(1, Math.abs(y(v) - y(0)));
      return (
        <rect
          key={i}
          x={round(PAD + i * slot + (slot - barWidth) / 2)}
          y={round(top)}
          width={round(barWidth)}
          height={round(barHeight)}
          rx={Math.min(1.5, barWidth / 2)}
          fill={stroke}
        />
      );
    });
  } else if (values.length > 0) {
    const lo = Math.min(...values);
    const hi = Math.max(...values);
    const inner = height - PAD * 2;
    const x = (i: number) => (values.length === 1 ? width / 2 : PAD + (i * (width - PAD * 2)) / (values.length - 1));
    // Flat data draws a centered line.
    const y = (v: number) => (hi === lo ? height / 2 : PAD + ((hi - v) / (hi - lo)) * inner);
    const points = values.map((v, i) => `${round(x(i))},${round(y(v))}`);
    const last = values.length - 1;
    shapes = (
      <>
        {values.length > 1 && (
          <polyline
            points={points.join(" ")}
            fill="none"
            stroke={stroke}
            strokeWidth={1.5}
            strokeLinejoin="round"
            strokeLinecap="round"
            vectorEffect="non-scaling-stroke"
          />
        )}
        {(showLast || values.length === 1) && <circle cx={round(x(last))} cy={round(y(values[last]))} r={2} fill={stroke} />}
      </>
    );
  }

  return (
    <svg
      focusable="false"
      {...rest}
      {...a11y}
      ref={ref}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      data-type={type}
    >
      {shapes}
    </svg>
  );
});

// Generated by rdloom codegen from specs/sparkline.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const sparklineTypeValues = ["line", "bar"] as const;
export const sparklineColorValues = ["primary", "success", "danger", "muted"] as const;

/** A tiny line or bar graphic that shows the shape of a trend, without axes. Decoration unless it has a label. */
export interface SparklineSpecProps {
  /**
   * The values, oldest first. Non-numbers are ignored.
   */
  data: number[];
  /**
   * A line, or thin bars from a zero baseline.
   * @default "line"
   */
  type?: "line" | "bar";
  /**
   * A text description, e.g. "Revenue, last 12 months: from 21K to 48K". Without it the graphic is hidden from assistive technology.
   */
  label?: string;
  /**
   * Width in pixels.
   * @default 96
   */
  width?: number;
  /**
   * Height in pixels.
   * @default 32
   */
  height?: number;
  /**
   * Color of the line or bars.
   * @default "primary"
   */
  color?: "primary" | "success" | "danger" | "muted";
  /**
   * Marks the last point of a line with a dot.
   * @default true
   */
  showLast?: boolean;
}

export const sparklineDefaults = {
  type: "line",
  width: 96,
  height: 32,
  color: "primary",
  showLast: true,
} as const;

export const sparklineMeta = {
  "name": "Sparkline",
  "version": "0.1.0",
  "status": "experimental",
  "role": "img"
} as const;
